content.solution_code:
class Robot {
  constructor(name) {
    this.name = name;
    this.equippedArm = null;
  }

  equipArm(arm) {
    this.equippedArm = arm;
  }

  performTask() {
    if (this.equippedArm) {
      return `Robot ${this.name} is performing: ${this.equippedArm.getAction()}`;
    } else {
      return `Robot ${this.name} has no arm equipped to perform tasks.`
    }
  }
}

class GripperArm {
  constructor(actionDescription) {
    this.actionDescription = actionDescription;
  }

  getAction() {
    return this.actionDescription;
  }
}

